import("net/http";"net/http/pprof";"crypto/subtle";"strconv";"errors")
func PublicHandler()http.Handler{
 mux:=http.NewServeMux();mux.HandleFunc("GET /healthz",func(w http.ResponseWriter,r *http.Request){w.Write([]byte("healthy"))});return mux
}
func DiagnosticHandler(token string,maxSeconds int)(http.Handler,error){
 if len(token)<16||maxSeconds<1||maxSeconds>5{return nil,errors.New("strong token and bounded profile duration required")}
 slots:=make(chan struct{},1)
 return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  expected:="Bearer "+token
  if subtle.ConstantTimeCompare([]byte(r.Header.Get("Authorization")),[]byte(expected))!=1{w.Header().Set("WWW-Authenticate","Bearer");http.Error(w,"unauthorized",http.StatusUnauthorized);return}
  if r.Method!=http.MethodGet{w.Header().Set("Allow","GET");http.Error(w,"method",http.StatusMethodNotAllowed);return}
  var handler http.HandlerFunc
  switch r.URL.Path{case "/debug/pprof/":handler=pprof.Index;case "/debug/pprof/goroutine":handler=pprof.Handler("goroutine").ServeHTTP;case "/debug/pprof/heap":handler=pprof.Handler("heap").ServeHTTP;case "/debug/pprof/profile":
   values:=r.URL.Query();seconds:="1";if all,ok:=values["seconds"];ok{if len(all)!=1{http.Error(w,"duration",400);return};seconds=all[0]}
   n,err:=strconv.Atoi(seconds);if err!=nil||n<1||n>maxSeconds{http.Error(w,"duration",400);return}
   values.Set("seconds",strconv.Itoa(n));r=r.Clone(r.Context());url:=*r.URL;url.RawQuery=values.Encode();r.URL=&url;handler=pprof.Profile
  default:http.NotFound(w,r);return}
  select{case slots<-struct{}{}:defer func(){<-slots}();default:http.Error(w,"diagnostic already active",http.StatusServiceUnavailable);return}
  handler(w,r)
 }),nil
}
