package exercise
import("testing";"net/http";"net/http/httptest";"strings";"io";"time";"sync")
const token="isolated-test-diagnostic-token-123"
func call(t *testing.T,client *http.Client,base,path,method,auth string)(int,string){t.Helper();req,_:=http.NewRequest(method,base+path,nil);if auth!=""{req.Header.Set("Authorization",auth)};res,err:=client.Do(req);if err!=nil{t.Fatal(err)};defer res.Body.Close();body,_:=io.ReadAll(io.LimitReader(res.Body,100000));return res.StatusCode,string(body)}
func TestPublicMuxNeverPublishesRuntimeDiagnostics(t *testing.T){
 server:=httptest.NewServer(PublicHandler());defer server.Close()
 if status,body:=call(t,server.Client(),server.URL,"/healthz","GET","");status!=200||body!="healthy"{t.Fatal("health",status,body)}
 for _,path:=range []string{"/debug/pprof/","/debug/pprof/goroutine?debug=1","/debug/pprof/profile?seconds=1"}{if status,_:=call(t,server.Client(),server.URL,path,"GET","Bearer "+token);status!=404{t.Fatal("public runtime leak",path,status)}}
}
func TestAdminAuthMethodsAndDuration(t *testing.T){
 handler,err:=DiagnosticHandler(token,1);if err!=nil{t.Fatal(err)};server:=httptest.NewServer(handler);defer server.Close();client:=server.Client();client.Timeout=3*time.Second
 for _,auth:=range []string{"","Bearer wrong",token}{if status,_:=call(t,client,server.URL,"/debug/pprof/goroutine?debug=1","GET",auth);status!=401{t.Fatal("unprotected stack",status)}}
 if status,_:=call(t,client,server.URL,"/debug/pprof/","POST","Bearer "+token);status!=405{t.Fatal("mutation method accepted",status)}
 if status,body:=call(t,client,server.URL,"/debug/pprof/goroutine?debug=1","GET","Bearer "+token);status!=200||!strings.Contains(body,"goroutine profile:"){t.Fatal("real runtime profile missing",status,body)}
 for _,query:=range []string{"seconds=0","seconds=-1","seconds=2","seconds=oops","seconds=1&seconds=1"}{if status,_:=call(t,client,server.URL,"/debug/pprof/profile?"+query,"GET","Bearer "+token);status!=400{t.Fatal("unbounded profile admitted",query,status)}}
 if status,_:=call(t,client,server.URL,"/debug/pprof/trace","GET","Bearer "+token);status!=404{t.Fatal("unapproved trace exposed",status)}
 for _,n:=range []int{0,6}{if _,err:=DiagnosticHandler(token,n);err==nil{t.Fatal("bad max duration")}}
 if _,err:=DiagnosticHandler("weak",1);err==nil{t.Fatal("weak token accepted")}
}
func TestConcurrentCpuProfilesHaveOneSlot(t *testing.T){
 handler,err:=DiagnosticHandler(token,1);if err!=nil{t.Fatal(err)};server:=httptest.NewServer(handler);defer server.Close()
 start:=make(chan struct{});results:=make(chan int,2);var wg sync.WaitGroup
 for i:=0;i<2;i++{wg.Add(1);go func(){defer wg.Done();<-start;req,_:=http.NewRequest("GET",server.URL+"/debug/pprof/profile?seconds=1",nil);req.Header.Set("Authorization","Bearer "+token);response,err:=server.Client().Do(req);if err!=nil{results<-0;return};_,_=io.Copy(io.Discard,response.Body);response.Body.Close();results<-response.StatusCode}()}
 close(start);wg.Wait();close(results);counts:=map[int]int{};for status:=range results{counts[status]++};if counts[200]!=1||counts[503]!=1{t.Fatal("profile concurrency budget",counts)}
 if status,_:=call(t,server.Client(),server.URL,"/debug/pprof/","GET","Bearer "+token);status!=200{t.Fatal("slot not released after profile",status)}
}
